-- ===========================================================================
-- Hand-written: invariants Prisma cannot express
-- ===========================================================================

-- 1. Row CHECKs -------------------------------------------------------------------

ALTER TABLE "finora"."financial_accounts"
  ADD CONSTRAINT "financial_accounts_name_format" CHECK (
    char_length("name") BETWEEN 1 AND 60 AND "name" = btrim("name")
  ),
  ADD CONSTRAINT "financial_accounts_creation_key_format" CHECK (
    "creation_key" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
  ),
  ADD CONSTRAINT "financial_accounts_creation_fingerprint_format" CHECK ("creation_fingerprint" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "financial_accounts_updated_after_created" CHECK ("updated_at" >= "created_at"),
  ADD CONSTRAINT "financial_accounts_archived_after_created" CHECK ("archived_at" IS NULL OR "archived_at" >= "created_at");

ALTER TABLE "finora"."categories"
  ADD CONSTRAINT "categories_name_format" CHECK (
    char_length("name") BETWEEN 1 AND 60 AND "name" = btrim("name")
  ),
  ADD CONSTRAINT "categories_updated_after_created" CHECK ("updated_at" >= "created_at"),
  ADD CONSTRAINT "categories_archived_after_created" CHECK ("archived_at" IS NULL OR "archived_at" >= "created_at");

ALTER TABLE "finora"."transactions"
  ADD CONSTRAINT "transactions_amount_positive" CHECK ("amount_minor" > 0),
  ADD CONSTRAINT "transactions_payee_format" CHECK (
    "payee" IS NULL OR (char_length("payee") BETWEEN 1 AND 100 AND "payee" = btrim("payee"))
  ),
  ADD CONSTRAINT "transactions_note_format" CHECK (
    "note" IS NULL OR (char_length("note") BETWEEN 1 AND 500 AND "note" = btrim("note"))
  ),
  -- Which accounts and category each kind uses (the posting templates).
  ADD CONSTRAINT "transactions_shape" CHECK (
    CASE "kind"
      WHEN 'income' THEN "destination_account_id" IS NOT NULL AND "source_account_id" IS NULL AND "category_id" IS NOT NULL
      WHEN 'expense' THEN "source_account_id" IS NOT NULL AND "destination_account_id" IS NULL AND "category_id" IS NOT NULL
      WHEN 'transfer' THEN "source_account_id" IS NOT NULL AND "destination_account_id" IS NOT NULL AND "category_id" IS NULL
        AND "source_account_id" <> "destination_account_id"
      WHEN 'opening_balance' THEN "destination_account_id" IS NOT NULL AND "source_account_id" IS NULL AND "category_id" IS NULL
    END
  ),
  ADD CONSTRAINT "transactions_voided_pair" CHECK (("voided_at" IS NULL) = ("reversal_entry_id" IS NULL)),
  ADD CONSTRAINT "transactions_updated_after_created" CHECK ("updated_at" >= "created_at");

-- 2. Financial accounts -------------------------------------------------------------
-- Backed by an asset ledger account of the same owner and currency (composite
-- foreign key + this check). Identity, currency and ledger link never change.
-- Deleting is only possible without any ledger history (and the foreign keys
-- from transactions also restrict it); otherwise archive.
CREATE FUNCTION "finora"."financial_accounts_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM finora.ledger_accounts AS la
       WHERE la.id = NEW.ledger_account_id AND la.owner_id = NEW.owner_id AND la.kind = 'asset'
    ) THEN
      RAISE EXCEPTION 'finora.finance: a financial account must be backed by an asset ledger account'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := NEW.created_at;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    IF EXISTS (SELECT 1 FROM finora.journal_lines AS l WHERE l.account_id = OLD.ledger_account_id) THEN
      RAISE EXCEPTION 'finora.finance: an account with ledger history cannot be deleted; archive it instead'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    RETURN OLD;
  END IF;

  IF NEW.id <> OLD.id OR NEW.owner_id <> OLD.owner_id OR NEW.currency_code <> OLD.currency_code
     OR NEW.ledger_account_id <> OLD.ledger_account_id OR NEW.creation_key <> OLD.creation_key
     OR NEW.creation_fingerprint <> OLD.creation_fingerprint OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'finora.finance: an account''s identity, currency and ledger account are immutable'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  NEW.updated_at := greatest(now(), OLD.updated_at);
  RETURN NEW;
END;
$$;

CREATE TRIGGER "financial_accounts_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "finora"."financial_accounts"
  FOR EACH ROW EXECUTE FUNCTION "finora"."financial_accounts_guard"();

-- 3. Categories ----------------------------------------------------------------------
CREATE FUNCTION "finora"."categories_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    NEW.updated_at := NEW.created_at;
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.owner_id <> OLD.owner_id OR NEW.kind <> OLD.kind OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'finora.finance: a category''s identity and kind are immutable'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  NEW.updated_at := greatest(now(), OLD.updated_at);
  RETURN NEW;
END;
$$;

CREATE TRIGGER "categories_guard"
  BEFORE INSERT OR UPDATE ON "finora"."categories"
  FOR EACH ROW EXECUTE FUNCTION "finora"."categories_guard"();

-- 4. Ledger-account mappings (insert-only) ------------------------------------------
-- A category posts to a ledger account of its own kind; the opening-balance
-- system account is an equity account.
CREATE FUNCTION "finora"."ledger_mappings_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
DECLARE
  expected finora.ledger_account_kind;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'finora.finance: % rows are immutable', TG_TABLE_NAME
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF TG_TABLE_NAME = 'category_ledger_accounts' THEN
    SELECT c.kind::text::finora.ledger_account_kind INTO expected
      FROM finora.categories AS c WHERE c.id = NEW.category_id AND c.owner_id = NEW.owner_id;
  ELSE
    expected := 'equity';
  END IF;
  IF expected IS NULL OR NOT EXISTS (
    SELECT 1 FROM finora.ledger_accounts AS la
     WHERE la.id = NEW.ledger_account_id AND la.owner_id = NEW.owner_id AND la.kind = expected
  ) THEN
    RAISE EXCEPTION 'finora.finance: the mapped ledger account has the wrong kind'
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.created_at := now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER "category_ledger_accounts_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "finora"."category_ledger_accounts"
  FOR EACH ROW EXECUTE FUNCTION "finora"."ledger_mappings_guard"();
CREATE TRIGGER "system_ledger_accounts_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "finora"."system_ledger_accounts"
  FOR EACH ROW EXECUTE FUNCTION "finora"."ledger_mappings_guard"();

-- 5. Transactions: creation rules ------------------------------------------------------
-- SECURITY DEFINER so the checks and row locks see true state whatever the
-- caller's RLS context; every lookup is restricted to the row's own owner.
--  * no new transaction on an archived account or category (the account row
--    is locked FOR SHARE, so a concurrent archive waits or is waited for);
--  * the category's kind matches the transaction's kind;
--  * at most one active (non-voided) opening balance per account (the account
--    row is locked FOR UPDATE, serialising concurrent attempts);
--  * created as not voided, with database timestamps.
CREATE FUNCTION "finora"."transactions_insert_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
DECLARE
  account_id uuid;
  archived timestamptz;
  category_kind finora.category_kind;
  category_archived timestamptz;
BEGIN
  IF NEW.voided_at IS NOT NULL OR NEW.reversal_entry_id IS NOT NULL THEN
    RAISE EXCEPTION 'finora.finance: transactions are created unvoided'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  FOREACH account_id IN ARRAY ARRAY[NEW.source_account_id, NEW.destination_account_id]
  LOOP
    CONTINUE WHEN account_id IS NULL;
    IF NEW.kind = 'opening_balance' THEN
      SELECT fa.archived_at INTO archived FROM finora.financial_accounts AS fa
       WHERE fa.id = account_id AND fa.owner_id = NEW.owner_id FOR UPDATE;
    ELSE
      SELECT fa.archived_at INTO archived FROM finora.financial_accounts AS fa
       WHERE fa.id = account_id AND fa.owner_id = NEW.owner_id FOR SHARE;
    END IF;
    -- A missing account falls through to the composite foreign key.
    IF archived IS NOT NULL THEN
      RAISE EXCEPTION 'finora.finance: archived accounts cannot take new transactions'
        USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;

  IF NEW.category_id IS NOT NULL THEN
    SELECT c.kind, c.archived_at INTO category_kind, category_archived FROM finora.categories AS c
     WHERE c.id = NEW.category_id AND c.owner_id = NEW.owner_id FOR SHARE;
    IF FOUND AND category_kind::text <> NEW.kind::text THEN
      RAISE EXCEPTION 'finora.finance: the category kind does not match the transaction'
        USING ERRCODE = 'check_violation';
    END IF;
    IF category_archived IS NOT NULL THEN
      RAISE EXCEPTION 'finora.finance: archived categories cannot take new transactions'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF NEW.kind = 'opening_balance' AND EXISTS (
    SELECT 1 FROM finora.transactions AS t
     WHERE t.destination_account_id = NEW.destination_account_id AND t.owner_id = NEW.owner_id
       AND t.kind = 'opening_balance' AND t.voided_at IS NULL
  ) THEN
    RAISE EXCEPTION 'finora.finance: the account already has an opening balance; correct it instead'
      USING ERRCODE = 'unique_violation';
  END IF;

  NEW.created_at := now();
  NEW.updated_at := NEW.created_at;
  RETURN NEW;
END;
$$;

CREATE TRIGGER "transactions_insert_guard"
  BEFORE INSERT ON "finora"."transactions"
  FOR EACH ROW EXECUTE FUNCTION "finora"."transactions_insert_guard"();

-- 6. Transactions: immutability ---------------------------------------------------------
-- Only metadata (payee, note) may change, plus a one-way void that links the
-- posted reversal. Nothing that has an accounting effect can be edited, and
-- transactions are never deleted.
CREATE FUNCTION "finora"."transactions_update_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'finora.finance: transactions are never deleted; void them instead'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.id <> OLD.id OR NEW.owner_id <> OLD.owner_id OR NEW.kind <> OLD.kind
     OR NEW.occurred_on <> OLD.occurred_on OR NEW.amount_minor <> OLD.amount_minor
     OR NEW.currency_code <> OLD.currency_code
     OR NEW.source_account_id IS DISTINCT FROM OLD.source_account_id
     OR NEW.destination_account_id IS DISTINCT FROM OLD.destination_account_id
     OR NEW.category_id IS DISTINCT FROM OLD.category_id
     OR NEW.journal_entry_id <> OLD.journal_entry_id
     OR NEW.replaces_transaction_id IS DISTINCT FROM OLD.replaces_transaction_id
     OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'finora.finance: a transaction''s accounting fields are immutable; void and re-enter it'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.reversal_entry_id IS NOT NULL THEN
    IF NEW.reversal_entry_id IS DISTINCT FROM OLD.reversal_entry_id OR NEW.voided_at IS DISTINCT FROM OLD.voided_at THEN
      RAISE EXCEPTION 'finora.finance: a void cannot be undone or changed'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  ELSIF NEW.reversal_entry_id IS NOT NULL THEN
    NEW.voided_at := now();
  ELSIF NEW.voided_at IS NOT NULL THEN
    RAISE EXCEPTION 'finora.finance: voided_at is set only by linking a reversal'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  NEW.updated_at := greatest(now(), OLD.updated_at);
  RETURN NEW;
END;
$$;

CREATE TRIGGER "transactions_update_guard"
  BEFORE UPDATE OR DELETE ON "finora"."transactions"
  FOR EACH ROW EXECUTE FUNCTION "finora"."transactions_update_guard"();

CREATE TRIGGER "transactions_no_truncate"
  BEFORE TRUNCATE ON "finora"."transactions"
  FOR EACH STATEMENT EXECUTE FUNCTION "finora"."ledger_no_truncate"();

-- 7. Transactions: agreement with the ledger, checked at COMMIT -----------------------
-- A transaction must record a posted, non-reversal journal entry whose lines
-- are EXACTLY its posting template (two lines, the right ledger accounts and
-- sides, the transaction's amount):
--   income           Dr destination asset     Cr category income account
--   expense          Dr category expense acct Cr source asset
--   transfer         Dr destination asset     Cr source asset
--   opening_balance  Dr destination asset     Cr opening-balance equity
-- A void must link the posted reversal of that entry; a replacement must
-- record the entry that replaced the voided original's entry.
CREATE FUNCTION "finora"."assert_transaction_valid"(target uuid) RETURNS void
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
DECLARE
  t finora.transactions%ROWTYPE;
  entry finora.journal_entries%ROWTYPE;
  counterpart uuid;
  debit_account uuid;
  credit_account uuid;
  original finora.transactions%ROWTYPE;
BEGIN
  SELECT * INTO t FROM finora.transactions WHERE id = target;
  IF NOT FOUND THEN RETURN; END IF;

  SELECT * INTO entry FROM finora.journal_entries WHERE id = t.journal_entry_id;
  IF entry.status <> 'posted' OR entry.reverses_entry_id IS NOT NULL THEN
    RAISE EXCEPTION 'finora.finance: a transaction must record a posted, non-reversal journal entry'
      USING ERRCODE = 'check_violation';
  END IF;

  IF t.kind IN ('income', 'expense') THEN
    SELECT m.ledger_account_id INTO counterpart FROM finora.category_ledger_accounts AS m
     WHERE m.category_id = t.category_id AND m.owner_id = t.owner_id AND m.currency_code = t.currency_code;
  ELSIF t.kind = 'opening_balance' THEN
    SELECT m.ledger_account_id INTO counterpart FROM finora.system_ledger_accounts AS m
     WHERE m.owner_id = t.owner_id AND m.purpose = 'opening_balance_equity' AND m.currency_code = t.currency_code;
  END IF;

  debit_account := CASE t.kind
    WHEN 'expense' THEN counterpart
    ELSE (SELECT fa.ledger_account_id FROM finora.financial_accounts AS fa WHERE fa.id = t.destination_account_id)
  END;
  credit_account := CASE t.kind
    WHEN 'income' THEN counterpart
    WHEN 'opening_balance' THEN counterpart
    ELSE (SELECT fa.ledger_account_id FROM finora.financial_accounts AS fa WHERE fa.id = t.source_account_id)
  END;

  IF debit_account IS NULL OR credit_account IS NULL
     OR (SELECT count(*) FROM finora.journal_lines WHERE entry_id = t.journal_entry_id) <> 2
     OR NOT EXISTS (SELECT 1 FROM finora.journal_lines WHERE entry_id = t.journal_entry_id
                     AND account_id = debit_account AND side = 'debit' AND amount_minor = t.amount_minor)
     OR NOT EXISTS (SELECT 1 FROM finora.journal_lines WHERE entry_id = t.journal_entry_id
                     AND account_id = credit_account AND side = 'credit' AND amount_minor = t.amount_minor) THEN
    RAISE EXCEPTION 'finora.finance: the journal entry does not match the transaction'
      USING ERRCODE = 'check_violation';
  END IF;

  IF t.reversal_entry_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM finora.journal_entries
     WHERE id = t.reversal_entry_id AND status = 'posted' AND reverses_entry_id = t.journal_entry_id
  ) THEN
    RAISE EXCEPTION 'finora.finance: a void must link the posted reversal of the transaction''s entry'
      USING ERRCODE = 'check_violation';
  END IF;

  IF t.replaces_transaction_id IS NOT NULL THEN
    SELECT * INTO original FROM finora.transactions WHERE id = t.replaces_transaction_id;
    IF original.kind <> t.kind OR original.reversal_entry_id IS NULL
       OR entry.replaces_entry_id IS DISTINCT FROM original.journal_entry_id THEN
      RAISE EXCEPTION 'finora.finance: a replacement must record the entry that replaced the voided original'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF t.kind = 'opening_balance' AND (
    SELECT count(*) FROM finora.transactions
     WHERE destination_account_id = t.destination_account_id AND kind = 'opening_balance' AND voided_at IS NULL
  ) > 1 THEN
    RAISE EXCEPTION 'finora.finance: an account can have only one active opening balance'
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$;

CREATE FUNCTION "finora"."transactions_validate"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
BEGIN
  PERFORM finora.assert_transaction_valid(NEW.id);
  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER "transactions_validate"
  AFTER INSERT OR UPDATE ON "finora"."transactions"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "finora"."transactions_validate"();

REVOKE ALL ON FUNCTION "finora"."financial_accounts_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."categories_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."ledger_mappings_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."transactions_insert_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."transactions_update_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."assert_transaction_valid"(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."transactions_validate"() FROM PUBLIC;

-- 8. Privileges and RLS ---------------------------------------------------------------
DO $$
DECLARE
  api_role text;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role', 'authenticator']
  LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE format(
        'REVOKE ALL ON finora.financial_accounts, finora.categories, finora.category_ledger_accounts, '
        'finora.system_ledger_accounts, finora.transactions FROM %I', api_role);
    END IF;
  END LOOP;
END
$$;
REVOKE ALL ON "finora"."financial_accounts", "finora"."categories", "finora"."category_ledger_accounts",
  "finora"."system_ledger_accounts", "finora"."transactions" FROM PUBLIC;

GRANT SELECT, INSERT, DELETE ON "finora"."financial_accounts" TO finora_app;
GRANT UPDATE ("name", "type", "archived_at") ON "finora"."financial_accounts" TO finora_app;
GRANT SELECT, INSERT ON "finora"."categories" TO finora_app;
GRANT UPDATE ("name", "archived_at") ON "finora"."categories" TO finora_app;
GRANT SELECT, INSERT ON "finora"."category_ledger_accounts", "finora"."system_ledger_accounts" TO finora_app;
GRANT SELECT, INSERT ON "finora"."transactions" TO finora_app;
GRANT UPDATE ("payee", "note", "reversal_entry_id") ON "finora"."transactions" TO finora_app;
-- Removing a never-used account also removes its ledger account. Foreign keys
-- (journal lines, financial accounts, mappings) restrict this to unused ones.
GRANT DELETE ON "finora"."ledger_accounts" TO finora_app;

SELECT finora.apply_owner_isolation('finora.financial_accounts');
SELECT finora.apply_owner_isolation('finora.categories');
SELECT finora.apply_owner_isolation('finora.category_ledger_accounts');
SELECT finora.apply_owner_isolation('finora.system_ledger_accounts');
SELECT finora.apply_owner_isolation('finora.transactions');
